export const FIGHTERS=[{id:'green',name:'Green Hopper',price:0},{id:'blue',name:'Blue Splash',price:25},{id:'purple',name:'Purple Punch',price:50},{id:'pink',name:'Pink Petal',price:75},{id:'gold',name:'Golden Glow',price:150},{id:'red',name:'Red Rocket',price:200},{id:'rainbow',name:'Rainbow Leap',price:500},{id:'trail-gold',name:'Golden Trail Frog',unlock:'Complete the Trophy Trail',emoji:'🐸👑'},{id:'pumpkin',name:'Pumpkin Hopper',unlock:'Win the Halloween championship',emoji:'🐸🎃'},{id:'snowflake',name:'Snowflake Hopper',unlock:'Win the Winter championship',emoji:'🐸❄️'}];
FIGHTERS.push(...buildCosmetics());
FIGHTERS.push(...[{id:'crystal',name:'Crystal Glow',price:300,hue:140},{id:'moon',name:'Moonlight',price:350,hue:180},{id:'aurora',name:'Aurora',price:400,hue:100},{id:'prism',name:'Prismatic',price:450,hue:220},{id:'seer',name:'Seer Frog',price:300,hue:210},{id:'scout',name:'Scout Frog',price:400,hue:130},{id:'memory',name:'Memory Frog',price:550,hue:260},{id:'lucky',name:'Lucky Frog',price:700,hue:40},{id:'mobile-guardian',name:'Mobile Pond Guardian',price:600,hue:20}].map(f=>({...f,collection:true,emblem:'✨',style:'Hopper'})));
export const POWERS=[{id:'vision',name:'Frog Vision',price:4,icon:'🌀',desc:'Peek at two hidden cards for one second.'},{id:'double',name:'Double Hopper',price:5,icon:'⭐',desc:'Your next matching pair earns two extra points.'},{id:'freeze',name:'Frog Freeze',price:6,icon:'❄️',desc:'Skip the rival’s next turn. Rival games only.'}];
POWERS.push(
 {id:'clock',name:'Dragonfly Time',price:4,icon:'⏳',desc:'Add five seconds to your current rival-game turn.'},
 {id:'link',name:'Lily Link',price:7,icon:'🪷',desc:'Peek at a matching hidden pair for one second.'},
 {id:'spotlight',name:'Firefly Spotlight',price:2,icon:'✨',desc:'Peek at one hidden card for one second.'},
 {id:'safe',name:'Soft Landing',price:5,icon:'🍃',desc:'Keep your turn after your next mismatch. Rival games only.'},
 {id:'shield',name:'Reed Shield',price:6,icon:'🛡️',desc:'Block the points from the rival’s next pair.'},
 {id:'harvest',name:'Fly Harvest',price:5,icon:'🪰',desc:'Your next matching pair adds three frogs to your round reward.'},
 {id:'recall',name:'Pond Recall',price:3,icon:'💭',desc:'Peek again at the last mismatched pair.'},
 {id:'shuffle',name:'Ripple Shuffle',price:4,icon:'🌊',desc:'Reshuffle hidden cards. Matched pairs stay put.'},
 {id:'lantern',name:'Moon Lantern',price:12,icon:'🌙',desc:'Reveal all hidden cards for one second.'},
 {id:'echo',name:'Echo Hopper',price:7,icon:'🎵',desc:'Your next two matching pairs earn one extra point each.'}
);
POWERS.push({id:'feast',name:'Frog Feast',price:2,icon:'🍽️',desc:'Add three points to your current round.'},{id:'snatch',name:'Frog Snatch',price:5,icon:'🤏',desc:'Move up to three rival points to your score. Rival games only.'});
export const SYMBOLS=['🦁','🐯','🐘','🦒','🐼','🐨','🦊','🐰','🐹','🦔','🐻','🐶','🦦','🐱','🐷','🐵','🦓','🦏','🦛','🐮','🐴','🐺','🦝','🐸','🐧','🦉'];
export function freshProfile(){return {version:1,welcomeClaimed:false,bank:20,wins:0,rivalWins:0,selected:'green',owned:['green'],inventory:{},trail:[],season:{halloween:0,winter:0},seasonClaimed:[],records:{accuracy:0,comeback:0,cards:0},settings:{sound:true,motion:true,learning:'explore'},journey:{learned:[],reviews:0},crossword:{level:1,letters:{}},wordSearch:{level:1,found:[]},puzzleLearning:{checks:0,firstTry:0,attempts:0,pending:null,cycleOrder:[],cycleRounds:0},stage:12};}
export function loadProfile(raw){try{const x=JSON.parse(raw);if(!x||x.version!==1)return freshProfile();const p=freshProfile();p.welcomeClaimed=x.welcomeClaimed===true;for(const k of ['bank','wins','rivalWins'])if(Number.isFinite(x[k])&&x[k]>=0)p[k]=Math.floor(x[k]);p.owned=Array.isArray(x.owned)?[...new Set(['green',...x.owned.filter(id=>FIGHTERS.some(f=>f.id===id))])]:['green'];p.selected=p.owned.includes(x.selected)?x.selected:'green';p.trail=Array.isArray(x.trail)?x.trail.filter(i=>Number.isInteger(i)&&i>=0):[];p.seasonClaimed=Array.isArray(x.seasonClaimed)?x.seasonClaimed.filter(s=>['halloween','winter'].includes(s)):[];for(const f of POWERS)p.inventory[f.id]=Math.max(0,Math.floor(Number(x.inventory?.[f.id])||0));for(const s of ['halloween','winter'])p.season[s]=Math.max(0,Math.floor(Number(x.season?.[s])||0));for(const k of ['accuracy','comeback','cards'])p.records[k]=Math.max(0,Number(x.records?.[k])||0);p.journey={learned:Array.isArray(x.journey?.learned)?[...new Set(x.journey.learned.filter(id=>typeof id==='string'))]:[],reviews:Math.max(0,Math.floor(Number(x.journey?.reviews)||0))};p.settings={...p.settings,...x.settings};if(!['gentle','explore','challenge'].includes(p.settings.learning))p.settings.learning='explore';p.crossword={level:Math.max(1,Math.floor(Number(x.crossword?.level)||1)),letters:{}};if(x.crossword?.letters&&typeof x.crossword.letters==='object')for(const [key,value] of Object.entries(x.crossword.letters))if(/^[0-9]+,[0-9]+$/.test(key)&&/^[A-Z]$/.test(value))p.crossword.letters[key]=value;p.wordSearch={level:Math.max(1,Math.floor(Number(x.wordSearch?.level)||1)),found:Array.isArray(x.wordSearch?.found)?[...new Set(x.wordSearch.found.filter(w=>typeof w==='string'&&/^[A-Z]+$/.test(w)))]:[]};for(const mode of ['crossword','wordSearch']){const plan=x[mode]?.plan;if(plan&&LESSONS.some(l=>l.id===plan.lessonId))p[mode].plan={lessonId:plan.lessonId,legacy:plan.legacy===true,learned:Array.isArray(plan.learned)?plan.learned.filter(id=>LESSONS.some(l=>l.id===id)):[]};}for(const key of ['checks','firstTry','attempts','cycleRounds'])p.puzzleLearning[key]=Math.max(0,Math.floor(Number(x.puzzleLearning?.[key])||0));p.puzzleLearning.cycleOrder=Array.isArray(x.puzzleLearning?.cycleOrder)&&x.puzzleLearning.cycleOrder.length<4&&x.puzzleLearning.cycleOrder.every((v,i)=>v===i)?[...x.puzzleLearning.cycleOrder]:[];const pending=x.puzzleLearning?.pending;if(pending&&['crossword','wordsearch'].includes(pending.mode)&&LESSONS.some(l=>l.id===pending.lessonId)&&Number.isInteger(pending.level)&&pending.level>0)p.puzzleLearning.pending={mode:pending.mode,lessonId:pending.lessonId,level:pending.level,attempts:Math.max(0,Math.floor(Number(pending.attempts)||0))};p.stage=STAGES.includes(x.stage)?x.stage:12;return p;}catch{return freshProfile();}}
export function leagueFor(wins){let index=0;LEAGUES.forEach((l,i)=>{if(wins>=l.need)index=i});const current=LEAGUES[index],next=LEAGUES[index+1];return {current,next,remaining:next?Math.max(0,next.need-wins):0,progress:next?Math.min(1,(wins-current.need)/(next.need-current.need)):1};}
export function stageAvailable(profile,cards){return STAGES.includes(cards)&&(cards<=profile.stage||profile.wins>=STAGE_UNLOCKS[STAGES.indexOf(cards)]);}
export function makeDeck(count,rng=Math.random){if(!STAGES.includes(count))throw Error('Unsupported stage');const deck=SYMBOLS.slice(0,count/2).flatMap((value)=>[{value,matched:false},{value,matched:false}]);for(let i=deck.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}return deck;}
export class Match{
 constructor({mode='rival',cards=12,rng=Math.random}={}){this.mode=mode;this.deck=makeDeck(cards,rng);this.rng=rng;this.turn='you';this.scores={you:0,rival:0};this.memory=new Map();this.revealed=[];this.lock=false;this.done=false;this.attempts=0;this.pairs=0;this.maxDeficit=0;this.double=false;this.freeze=false;this.resultApplied=false;this.safe=false;this.shield=false;this.harvest=false;this.echo=0;this.bonusCurrency=0;this.lastMismatch=[];}
 select(i,actor=this.turn){if(this.done||this.lock||actor!==this.turn||!Number.isInteger(i)||!this.deck[i]||this.deck[i].matched||this.revealed.includes(i))return {type:'ignored'};this.revealed.push(i);this.memory.set(i,this.deck[i].value);while(this.memory.size>6)this.memory.delete(this.memory.keys().next().value);if(this.revealed.length<2)return {type:'first'};const [a,b]=this.revealed;if(actor==='you')this.attempts++;this.lock=true;if(this.deck[a].value===this.deck[b].value){this.deck[a].matched=this.deck[b].matched=true;let points=1+(actor==='you'&&this.double?2:0);if(actor==='you'&&this.echo>0){points++;this.echo--;}if(actor==='rival'&&this.shield){points=0;this.shield=false;}this.scores[actor]+=points;if(actor==='you'){this.pairs++;this.double=false;if(this.harvest){this.bonusCurrency+=3;this.harvest=false;}}this.maxDeficit=Math.max(this.maxDeficit,this.scores.rival-this.scores.you);this.memory.delete(a);this.memory.delete(b);return {type:'match',actor};}this.lastMismatch=[a,b];return {type:'mismatch',actor};}
 resolve(matched){this.revealed=[];this.lock=false;this.maxDeficit=Math.max(this.maxDeficit,this.scores.rival-this.scores.you);if(this.deck.every(c=>c.matched)){this.done=true;return 'finished';}if(!matched){if(this.turn==='you'&&this.safe){this.safe=false;}else this.nextTurn();}return this.turn;}
 nextTurn(){this.revealed=[];this.lock=false;if(this.mode==='solo'){this.turn='you';return;}if(this.turn==='you'){if(this.freeze){this.freeze=false;this.turn='you';}else this.turn='rival';}else this.turn='you';}
 botChoice(){const available=this.deck.map((c,i)=>!c.matched&&!this.revealed.includes(i)?i:null).filter(i=>i!==null);if(!available.length)return null;if(this.rng()<.25){if(this.revealed.length){const first=this.revealed[0],v=this.deck[first].value;const known=available.find(i=>this.memory.get(i)===v);if(known!==undefined)return known;}else{for(const i of available){const v=this.memory.get(i);if(v&&available.some(j=>j!==i&&this.memory.get(j)===v))return i;}}}return available[Math.floor(this.rng()*available.length)];}
 outcome(){return this.mode==='solo'?'win':this.scores.you>this.scores.rival?'win':this.scores.you===this.scores.rival?'tie':'loss';}
}
export function settle(profile,match,season=null){if(!match.done||match.resultApplied)return null;match.resultApplied=true;const outcome=match.outcome(),won=outcome==='win',oldLeague=leagueFor(profile.rivalWins).current.name;const accuracy=match.attempts?Math.round(100*match.pairs/match.attempts):0;const rewards=[];if(!match.learning){const index=STAGES.indexOf(match.deck.length);profile.stage=Math.max(profile.stage,STAGES[Math.min(index+1,STAGES.length-1)]);rewards.push(`Next stage: ${profile.stage} cards`);}let currency=match.pairs*2+(won?5:0)+match.bonusCurrency;rewards.push(`${match.pairs*2} frogs for matched pairs`);if(match.bonusCurrency)rewards.push(`${match.bonusCurrency} frogs from Fly Harvest`);if(won){profile.wins++;if(match.mode==='rival')profile.rivalWins++;rewards.push('5 frogs for the win');profile.records.cards=Math.max(profile.records.cards,match.deck.length);if(accuracy>profile.records.accuracy){profile.records.accuracy=accuracy;rewards.push(`Personal best: ${accuracy}% matching accuracy`);}if(match.mode==='rival'&&match.maxDeficit>profile.records.comeback){profile.records.comeback=match.maxDeficit;rewards.push(`Personal best: ${match.maxDeficit}-point comeback`);}const cycle=Math.floor((profile.wins-1)/12);for(let track=0;track<=cycle;track++)TRAIL.forEach((m,i)=>{const id=track*5+i,need=track*12+m.need,reward=m.reward+track*5;if(profile.wins>=need&&!profile.trail.includes(id)){profile.trail.push(id);currency+=reward;rewards.push(`Trail ${track+1} · ${m.name}: +${reward} frogs`);if(i===4&&track>0){const bonus=FIGHTERS[10+((track-1)*9)%242];if(!profile.owned.includes(bonus.id)){profile.owned.push(bonus.id);rewards.push(`${bonus.name} earned!`);}}}});if(profile.trail.filter(i=>i<5).length===5&&!profile.owned.includes('trail-gold')){profile.owned.push('trail-gold');rewards.push('Golden Trail Frog unlocked!');}if(season&&match.mode==='rival'){profile.season[season]++;if(profile.season[season]>=5&&!profile.seasonClaimed.includes(season)){profile.seasonClaimed.push(season);const costume=season==='halloween'?'pumpkin':'snowflake';if(!profile.owned.includes(costume))profile.owned.push(costume);currency+=50;rewards.push(`${season==='halloween'?'Pumpkin':'Snowflake'} Hopper + 50 frogs unlocked!`);}}}profile.bank+=currency;const newLeague=leagueFor(profile.rivalWins).current.name;return {outcome,accuracy,currency,rewards,newLeague};}

export const WELCOME_BONUS=30;
export function claimWelcomeBonus(profile){if(profile.welcomeClaimed)return 0;profile.welcomeClaimed=true;profile.bank+=WELCOME_BONUS;return WELCOME_BONUS;}
